package cn.wenjin.admission.web;

import cn.wenjin.admission.domain.Domain.RunEvent;import cn.wenjin.admission.workflow.*;import org.springframework.http.MediaType;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import java.io.IOException;import java.util.LinkedHashMap;import java.util.Map;import java.util.concurrent.atomic.AtomicReference;
@RestController @RequestMapping("/api/v1/runs") public class RunController {private final RunRepository runs;private final RunEventStore events;private final AdmissionAdvisorWorkflow workflow;public RunController(RunRepository r,RunEventStore e,AdmissionAdvisorWorkflow w){runs=r;events=e;workflow=w;}
 @GetMapping("/{id}")Object get(Authentication a,@PathVariable String id){String userId=WebSupport.user(a).id();Map<String,Object> response=new LinkedHashMap<>();response.put("run",runs.view(id,userId));response.put("state",runs.state(id,userId).orElse(null));return response;}
 @PostMapping("/{id}/retry")Object retry(Authentication a,@PathVariable String id){return workflow.retry(id,WebSupport.user(a).id());}
 @PostMapping("/{id}/cancel")Map<String,Object> cancel(Authentication a,@PathVariable String id){runs.requestCancel(id,WebSupport.user(a).id());return Map.of("cancelRequested",true);}
 @GetMapping(value="/{id}/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE)SseEmitter stream(Authentication a,@PathVariable String id,@RequestHeader(value="Last-Event-ID",required=false)String last){runs.view(id,WebSupport.user(a).id());long after=parse(last);SseEmitter emitter=new SseEmitter(180000L);AtomicReference<AutoCloseable> subscription=new AtomicReference<>();try{boolean terminalSeen=false;for(RunEvent event:events.replay(id,after)){send(emitter,event);if(terminal(event.event())){terminalSeen=true;break;}}if(terminalSeen){emitter.complete();return emitter;}subscription.set(events.subscribe(id,event->{try{send(emitter,event);if(terminal(event.event()))emitter.complete();}catch(Exception e){emitter.completeWithError(e);}}));emitter.send(SseEmitter.event().name("heartbeat").data(Map.of("runId",id)));}catch(Exception e){emitter.completeWithError(e);}Runnable close=()->{try{if(subscription.get()!=null)subscription.get().close();}catch(Exception ignored){}};emitter.onCompletion(close);emitter.onTimeout(close);emitter.onError(e->close.run());return emitter;}
 private static void send(SseEmitter e,RunEvent x)throws IOException{e.send(SseEmitter.event().id(String.valueOf(x.id())).name(x.event()).data(Map.of("timestamp",x.timestamp(),"data",x.data())));}private static long parse(String v){try{return v==null?0:Long.parseLong(v);}catch(Exception e){return 0;}}private static boolean terminal(String e){return e.equals("report_completed")||e.equals("run_failed")||e.equals("profile_question_required");}
}
